QString StepsLocalization::text(const QString&english,const QString&language){int c=column(language);if(!c)return english;QString result=lookup(labels,int(std::size(labels)),english,c);if(!result.isEmpty())return result;
    if(english.contains("arbitrary")||english.contains("additive constant"))return lookup(notes,int(std::size(notes)),"constant",c);
    if(english.contains("radian")||english.contains("Real domain where")||english.contains("real-domain restrictions"))return lookup(notes,int(std::size(notes)),"radians",c);
    // Before/after fields remain canonical mathematics; only human annotations
    // are translated. Function names and stored expressions are unchanged.
    result=english;
    const QStringList annotations={"Accepted","Rejected","does not exist","no inverse","No real breakpoints","Real domain","Real variable"};
    for(const auto&s:annotations){QString t=lookup(labels,int(std::size(labels)),s,c);result.replace(s,t);}
    const std::array<const char*,8> excluded={"kizárva","ausgeschlossen","exclu","excluido","escluso","исключено","排除","除外"};
    const std::array<const char*,8> zero={"zérushely","Nullstelle","zéro","cero","zero","ноль","零点","零点"};
    const std::array<const char*,8> negative={"negatív","negativ","négatif","negativo","negativo","отрицательно","负","負"};
    const std::array<const char*,8> positive={"pozitív","positiv","positif","positivo","positivo","положительно","正","正"};
    const std::array<const char*,8> left={"bal","links","gauche","izquierda","sinistra","слева","左","左"},right={"jobb","rechts","droite","derecha","destra","справа","右","右"};
    result.replace("(excluded)","("+QString::fromUtf8(excluded[c-1])+")");result.replace("(zero)","("+QString::fromUtf8(zero[c-1])+")");
    result.replace(": negative",": "+QString::fromUtf8(negative[c-1]));result.replace(": positive",": "+QString::fromUtf8(positive[c-1]));result.replace(": zero",": 0");result.replace("left:",QString::fromUtf8(left[c-1])+":");result.replace("right:",QString::fromUtf8(right[c-1])+":");
    result.replace("Real-domain interior point",lookup(labels,int(std::size(labels)),"Real domain",c));
    result.replace("u approaches 0","u → 0");result.replace("radicand =","√ argument =");result.replace("right side =","RHS =");
    return result;
}
QString StepsLocalization::explanation(const QString&rule,const QString&english,const QString&language){int c=column(language);if(!c)return english;QString out=lookup(rules,int(std::size(rules)),category(rule),c);return out.isEmpty()?text(english,language):out;}
QString StepsLocalization::status(const QString&english,const QString&language){int c=column(language);if(!c)return english;QString exact=lookup(labels,int(std::size(labels)),english,c);if(!exact.isEmpty())return exact;QString key="unsupported";
    if(english.contains("bound")||english.contains("exceed")||english.contains("at most")||english.contains("budget")||english.contains("too large")||english.contains("too close"))key="bound";
    if(english.contains("Missing")||english.contains("Invalid")||english.contains("Division by zero")||english.contains("Expected")||english.contains("must")||english.contains("Enter one")||english.contains("nowhere"))key="invalid";
    return lookup(notes,int(std::size(notes)),key,c);
}
QString StepsLocalization::coverage(const QString&language){return lookup(notes,int(std::size(notes)),"coverage",column(language));}
